//! API key management for per-agent authentication.
//!
//! Keys use `ngk_<32-hex-chars>` format, hashed with BLAKE3 before storage.
//! Supports scopes (`read`, `write`, `admin`) for fine-grained access control.

use std::sync::Arc;

use chrono::{DateTime, Utc};
use serde::Serialize;

use crate::db::SqliteDb;
use crate::error::Result;

/// An API key record (never contains the raw key).
#[derive(Debug, Clone, Serialize)]
pub struct ApiKeyRecord {
    pub id: String,
    pub name: String,
    pub key_prefix: String,
    pub scopes: Vec<String>,
    pub created_at: DateTime<Utc>,
    pub last_used_at: Option<DateTime<Utc>>,
    pub revoked_at: Option<DateTime<Utc>>,
    pub created_by: Option<String>,
}

impl ApiKeyRecord {
    /// Check if this key has the given scope.
    pub fn has_scope(&self, scope: &str) -> bool {
        self.scopes.iter().any(|s| s == scope || s == "admin")
    }

    /// Check if this key is currently active (not revoked).
    pub fn is_active(&self) -> bool {
        self.revoked_at.is_none()
    }
}

/// Store and manage API keys in SQLite.
pub struct ApiKeyStore {
    db: Arc<SqliteDb>,
}

impl ApiKeyStore {
    /// Create a new store, ensuring the schema exists.
    pub async fn new(db: Arc<SqliteDb>) -> Result<Self> {
        let store = Self { db };
        store.ensure_schema().await?;
        Ok(store)
    }

    async fn ensure_schema(&self) -> Result<()> {
        self.db
            .execute_batch(
                "CREATE TABLE IF NOT EXISTS api_keys (
                    id TEXT PRIMARY KEY,
                    name TEXT NOT NULL UNIQUE,
                    key_prefix TEXT NOT NULL,
                    key_hash TEXT NOT NULL UNIQUE,
                    scopes TEXT NOT NULL DEFAULT 'read,write',
                    created_at TEXT NOT NULL,
                    last_used_at TEXT,
                    revoked_at TEXT,
                    created_by TEXT
                )",
            )
            .await
    }

    /// Generate a new API key. Returns `(plaintext_key, record)`.
    /// The plaintext is shown once and never stored.
    pub async fn create_key(
        &self,
        name: &str,
        scopes: &[String],
        created_by: Option<&str>,
    ) -> Result<(String, ApiKeyRecord)> {
        let plaintext = generate_key();
        let key_hash = hash_key(&plaintext);
        let prefix = format!("ngk_{}", &plaintext[4..8]);
        let id = uuid::Uuid::new_v4().to_string();
        let now = Utc::now();
        let scopes_str = scopes.join(",");

        self.db
            .execute(
                "INSERT INTO api_keys (id, name, key_prefix, key_hash, scopes, created_at, created_by)
                 VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
                &[
                    &id as &dyn rusqlite::ToSql,
                    &name,
                    &prefix,
                    &key_hash,
                    &scopes_str,
                    &now.to_rfc3339(),
                    &created_by.map(|s| s.to_string()),
                ],
            )
            .await?;

        let record = ApiKeyRecord {
            id,
            name: name.to_string(),
            key_prefix: prefix,
            scopes: scopes.to_vec(),
            created_at: now,
            last_used_at: None,
            revoked_at: None,
            created_by: created_by.map(|s| s.to_string()),
        };

        Ok((plaintext, record))
    }

    /// Validate a plaintext key. Returns the record if active, None if missing/revoked.
    ///
    /// Uses `with_connection` to keep `&dyn ToSql` refs inside a sync closure,
    /// which avoids the non-`Send` future that axum handlers require.
    pub async fn validate_key(&self, plaintext: &str) -> Result<Option<ApiKeyRecord>> {
        let key_hash = hash_key(plaintext);

        self.db
            .with_connection(move |conn| {
                let mut stmt = conn
                    .prepare(
                        "SELECT id, name, key_prefix, scopes, created_at, last_used_at, revoked_at, created_by
                         FROM api_keys WHERE key_hash = ?1 AND revoked_at IS NULL",
                    )
                    .map_err(crate::error::DatabaseError::from)?;

                let mut rows = stmt
                    .query(rusqlite::params![key_hash])
                    .map_err(crate::error::DatabaseError::from)?;

                match rows.next().map_err(crate::error::DatabaseError::from)? {
                    Some(row) => {
                        let scopes_str: String = row.get(3).map_err(crate::error::DatabaseError::from)?;
                        Ok(Some(ApiKeyRecord {
                            id: row.get(0).map_err(crate::error::DatabaseError::from)?,
                            name: row.get(1).map_err(crate::error::DatabaseError::from)?,
                            key_prefix: row.get(2).map_err(crate::error::DatabaseError::from)?,
                            scopes: scopes_str.split(',').map(|s| s.trim().to_string()).collect(),
                            created_at: parse_dt(row.get::<_, String>(4).map_err(crate::error::DatabaseError::from)?),
                            last_used_at: row.get::<_, Option<String>>(5).map_err(crate::error::DatabaseError::from)?.map(parse_dt),
                            revoked_at: row.get::<_, Option<String>>(6).map_err(crate::error::DatabaseError::from)?.map(parse_dt),
                            created_by: row.get(7).map_err(crate::error::DatabaseError::from)?,
                        }))
                    }
                    None => Ok(None),
                }
            })
            .await
    }

    /// Update last_used_at for a key (fire-and-forget).
    ///
    /// Uses `with_connection` for Send-safety in axum handlers.
    pub async fn touch_last_used(&self, id: &str) -> Result<()> {
        let now = Utc::now().to_rfc3339();
        let id = id.to_string();
        self.db
            .with_connection(move |conn| {
                conn.execute(
                    "UPDATE api_keys SET last_used_at = ?1 WHERE id = ?2",
                    rusqlite::params![now, id],
                )
                .map_err(crate::error::DatabaseError::from)?;
                Ok(())
            })
            .await
    }

    /// List all keys, optionally including revoked ones.
    /// Whether at least one non-revoked key exists. Send-safe (usable from axum extractors),
    /// unlike `list_keys`, whose `query` params are `&dyn ToSql`.
    pub async fn has_active_keys(&self) -> Result<bool> {
        self.db
            .with_connection(|conn| {
                let n: i64 = conn
                    .query_row(
                        "SELECT COUNT(*) FROM api_keys WHERE revoked_at IS NULL",
                        [],
                        |row| row.get(0),
                    )
                    .map_err(crate::error::DatabaseError::from)?;
                Ok(n > 0)
            })
            .await
    }

    pub async fn list_keys(&self, include_revoked: bool) -> Result<Vec<ApiKeyRecord>> {
        let sql = if include_revoked {
            "SELECT id, name, key_prefix, scopes, created_at, last_used_at, revoked_at, created_by
             FROM api_keys ORDER BY created_at DESC"
        } else {
            "SELECT id, name, key_prefix, scopes, created_at, last_used_at, revoked_at, created_by
             FROM api_keys WHERE revoked_at IS NULL ORDER BY created_at DESC"
        };

        self.db
            .query(sql, &[], |row| {
                let scopes_str: String = row.get(3)?;
                Ok(ApiKeyRecord {
                    id: row.get(0)?,
                    name: row.get(1)?,
                    key_prefix: row.get(2)?,
                    scopes: scopes_str
                        .split(',')
                        .map(|s| s.trim().to_string())
                        .collect(),
                    created_at: parse_dt(row.get::<_, String>(4)?),
                    last_used_at: row.get::<_, Option<String>>(5)?.map(parse_dt),
                    revoked_at: row.get::<_, Option<String>>(6)?.map(parse_dt),
                    created_by: row.get(7)?,
                })
            })
            .await
    }

    /// Revoke a key by name or ID (soft-delete via revoked_at).
    pub async fn revoke_key(&self, name_or_id: &str) -> Result<bool> {
        let now = Utc::now().to_rfc3339();
        let rows = self
            .db
            .execute(
                "UPDATE api_keys SET revoked_at = ?1
                 WHERE (name = ?2 OR id = ?2) AND revoked_at IS NULL",
                &[&now as &dyn rusqlite::ToSql, &name_or_id],
            )
            .await?;
        Ok(rows > 0)
    }
}

/// Generate a random API key in `ngk_<32-hex-chars>` format.
pub fn generate_key() -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let mut bytes = [0u8; 16];
    rng.fill(&mut bytes);
    format!("ngk_{}", hex::encode(bytes))
}

/// BLAKE3-hash a plaintext key for storage.
pub fn hash_key(key: &str) -> String {
    let hash = blake3::hash(key.as_bytes());
    hash.to_hex().to_string()
}

/// Parse an RFC3339 datetime string, falling back to epoch on error.
fn parse_dt(s: String) -> DateTime<Utc> {
    DateTime::parse_from_rfc3339(&s)
        .map(|dt| dt.with_timezone(&Utc))
        .unwrap_or_else(|_| DateTime::UNIX_EPOCH)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_key_format() {
        let key = generate_key();
        assert!(key.starts_with("ngk_"), "Key should start with ngk_");
        assert_eq!(key.len(), 4 + 32, "Key should be ngk_ + 32 hex chars");
        // Verify hex chars after prefix
        assert!(key[4..].chars().all(|c| c.is_ascii_hexdigit()));
    }

    #[test]
    fn test_hash_key_deterministic() {
        let key = "ngk_0123456789abcdef0123456789abcdef";
        let h1 = hash_key(key);
        let h2 = hash_key(key);
        assert_eq!(h1, h2);
    }

    #[test]
    fn test_hash_key_different_inputs() {
        let h1 = hash_key("ngk_aaaa");
        let h2 = hash_key("ngk_bbbb");
        assert_ne!(h1, h2);
    }

    #[test]
    fn test_api_key_record_has_scope() {
        let rec = ApiKeyRecord {
            id: "test".into(),
            name: "test".into(),
            key_prefix: "ngk_1234".into(),
            scopes: vec!["read".into(), "write".into()],
            created_at: Utc::now(),
            last_used_at: None,
            revoked_at: None,
            created_by: None,
        };
        assert!(rec.has_scope("read"));
        assert!(rec.has_scope("write"));
        assert!(!rec.has_scope("admin"));
    }

    #[test]
    fn test_admin_scope_grants_all() {
        let rec = ApiKeyRecord {
            id: "test".into(),
            name: "admin-key".into(),
            key_prefix: "ngk_5678".into(),
            scopes: vec!["admin".into()],
            created_at: Utc::now(),
            last_used_at: None,
            revoked_at: None,
            created_by: None,
        };
        assert!(rec.has_scope("read"));
        assert!(rec.has_scope("write"));
        assert!(rec.has_scope("admin"));
    }

    #[test]
    fn test_is_active() {
        let mut rec = ApiKeyRecord {
            id: "test".into(),
            name: "test".into(),
            key_prefix: "ngk_1234".into(),
            scopes: vec!["read".into()],
            created_at: Utc::now(),
            last_used_at: None,
            revoked_at: None,
            created_by: None,
        };
        assert!(rec.is_active());
        rec.revoked_at = Some(Utc::now());
        assert!(!rec.is_active());
    }

    #[tokio::test]
    async fn test_store_create_and_validate() {
        let db = Arc::new(SqliteDb::open_in_memory().unwrap());
        let store = ApiKeyStore::new(db).await.unwrap();

        let (plaintext, record) = store
            .create_key("test-agent", &["read".into(), "write".into()], None)
            .await
            .unwrap();

        assert!(plaintext.starts_with("ngk_"));
        assert_eq!(record.name, "test-agent");
        assert_eq!(record.scopes, vec!["read", "write"]);

        // Validate
        let found = store.validate_key(&plaintext).await.unwrap();
        assert!(found.is_some());
        let found = found.unwrap();
        assert_eq!(found.name, "test-agent");
    }

    #[tokio::test]
    async fn test_store_revoke_and_validate() {
        let db = Arc::new(SqliteDb::open_in_memory().unwrap());
        let store = ApiKeyStore::new(db).await.unwrap();

        let (plaintext, _) = store
            .create_key("revoke-me", &["read".into()], None)
            .await
            .unwrap();

        // Revoke
        let revoked = store.revoke_key("revoke-me").await.unwrap();
        assert!(revoked);

        // Should no longer validate
        let found = store.validate_key(&plaintext).await.unwrap();
        assert!(found.is_none());
    }

    #[tokio::test]
    async fn test_store_list_keys() {
        let db = Arc::new(SqliteDb::open_in_memory().unwrap());
        let store = ApiKeyStore::new(db).await.unwrap();

        store
            .create_key("key-a", &["read".into()], None)
            .await
            .unwrap();
        store
            .create_key("key-b", &["write".into()], None)
            .await
            .unwrap();

        let active = store.list_keys(false).await.unwrap();
        assert_eq!(active.len(), 2);

        store.revoke_key("key-a").await.unwrap();

        let active = store.list_keys(false).await.unwrap();
        assert_eq!(active.len(), 1);

        let all = store.list_keys(true).await.unwrap();
        assert_eq!(all.len(), 2);
    }

    #[tokio::test]
    async fn test_store_touch_last_used() {
        let db = Arc::new(SqliteDb::open_in_memory().unwrap());
        let store = ApiKeyStore::new(db).await.unwrap();

        let (plaintext, record) = store
            .create_key("touch-me", &["read".into()], None)
            .await
            .unwrap();
        assert!(record.last_used_at.is_none());

        store.touch_last_used(&record.id).await.unwrap();

        let found = store.validate_key(&plaintext).await.unwrap().unwrap();
        assert!(found.last_used_at.is_some());
    }

    #[tokio::test]
    async fn test_store_duplicate_name_fails() {
        let db = Arc::new(SqliteDb::open_in_memory().unwrap());
        let store = ApiKeyStore::new(db).await.unwrap();

        store
            .create_key("unique", &["read".into()], None)
            .await
            .unwrap();
        let result = store.create_key("unique", &["read".into()], None).await;
        assert!(result.is_err());
    }
}

//! Privacy-preserving log redaction.
//!
//! Provides a tracing-subscriber layer that automatically redacts sensitive
//! information (PII) from log output using the security module's PII detector.

use std::collections::HashSet;
use std::fmt;
use std::sync::Arc;

use parking_lot::RwLock;
use tracing::{Event, Subscriber};
use tracing_subscriber::{
    fmt::{
        format::{self, FormatEvent, FormatFields},
        FmtContext,
    },
    layer::Context,
    registry::LookupSpan,
    Layer,
};

use crate::security::pii::{PiiClassification, PiiDetector, PiiMatch, PiiType};

/// Configuration for log redaction.
#[derive(Debug, Clone)]
pub struct RedactionConfig {
    /// Minimum PII classification level to redact (default: Medium).
    pub min_classification: PiiClassification,
    /// Whether to redact field names that match sensitive patterns.
    pub redact_field_names: bool,
    /// Additional field names to always redact.
    pub sensitive_fields: HashSet<String>,
    /// Redaction placeholder text.
    pub redaction_text: String,
    /// Whether to log redaction events.
    pub log_redactions: bool,
    /// Whether to preserve partial information (e.g., first/last chars).
    pub preserve_partial: bool,
}

impl Default for RedactionConfig {
    fn default() -> Self {
        let mut sensitive_fields = HashSet::new();
        sensitive_fields.insert("password".to_string());
        sensitive_fields.insert("secret".to_string());
        sensitive_fields.insert("token".to_string());
        sensitive_fields.insert("api_key".to_string());
        sensitive_fields.insert("apikey".to_string());
        sensitive_fields.insert("authorization".to_string());
        sensitive_fields.insert("auth".to_string());
        sensitive_fields.insert("credential".to_string());
        sensitive_fields.insert("private_key".to_string());
        sensitive_fields.insert("ssn".to_string());
        sensitive_fields.insert("credit_card".to_string());
        sensitive_fields.insert("card_number".to_string());

        Self {
            min_classification: PiiClassification::Medium,
            redact_field_names: true,
            sensitive_fields,
            redaction_text: "[REDACTED]".to_string(),
            log_redactions: false,
            preserve_partial: true,
        }
    }
}

impl RedactionConfig {
    /// Create a new config with default settings.
    pub fn new() -> Self {
        Self::default()
    }

    /// Set the minimum classification level to redact.
    pub fn with_min_classification(mut self, level: PiiClassification) -> Self {
        self.min_classification = level;
        self
    }

    /// Add a sensitive field name.
    pub fn with_sensitive_field(mut self, field: impl Into<String>) -> Self {
        self.sensitive_fields.insert(field.into());
        self
    }

    /// Set the redaction placeholder text.
    pub fn with_redaction_text(mut self, text: impl Into<String>) -> Self {
        self.redaction_text = text.into();
        self
    }

    /// Enable or disable partial preservation.
    pub fn with_preserve_partial(mut self, preserve: bool) -> Self {
        self.preserve_partial = preserve;
        self
    }

    /// Enable or disable logging of redaction events.
    pub fn with_log_redactions(mut self, log: bool) -> Self {
        self.log_redactions = log;
        self
    }

    /// Check if a field name is sensitive.
    pub fn is_sensitive_field(&self, name: &str) -> bool {
        let name_lower = name.to_lowercase();
        self.sensitive_fields.iter().any(|s| name_lower.contains(s))
    }
}

/// A log redactor that removes or masks PII from text.
pub struct LogRedactor {
    detector: PiiDetector,
    config: RedactionConfig,
    /// Count of redactions performed.
    redaction_count: RwLock<u64>,
}

impl LogRedactor {
    /// Create a new log redactor with default configuration.
    pub fn new() -> Self {
        Self {
            detector: PiiDetector::new(),
            config: RedactionConfig::default(),
            redaction_count: RwLock::new(0),
        }
    }

    /// Create a log redactor with custom configuration.
    pub fn with_config(config: RedactionConfig) -> Self {
        Self {
            detector: PiiDetector::new(),
            config,
            redaction_count: RwLock::new(0),
        }
    }

    /// Redact sensitive information from text.
    pub fn redact(&self, text: &str) -> String {
        let matches = self.detector.scan_text(text);

        if matches.is_empty() {
            return text.to_string();
        }

        let mut result = text.to_string();
        let mut offset: i64 = 0;

        // Sort matches by position (they should already be sorted)
        let mut relevant_matches: Vec<&PiiMatch> = matches
            .iter()
            .filter(|m| m.classification >= self.config.min_classification)
            .collect();

        relevant_matches.sort_by_key(|m| m.range.start);

        for pii_match in relevant_matches {
            let start = (pii_match.range.start as i64 + offset) as usize;
            let end = (pii_match.range.end as i64 + offset) as usize;

            if start >= result.len() || end > result.len() {
                continue;
            }

            let replacement = self.create_replacement(pii_match);
            let old_len = end - start;
            let new_len = replacement.len();

            result.replace_range(start..end, &replacement);
            offset += new_len as i64 - old_len as i64;

            // Increment redaction count
            *self.redaction_count.write() += 1;
        }

        result
    }

    /// Create a replacement string for a PII match.
    fn create_replacement(&self, pii_match: &PiiMatch) -> String {
        if self.config.preserve_partial && pii_match.matched_text.len() > 4 {
            pii_match.redacted_text()
        } else {
            self.config.redaction_text.clone()
        }
    }

    /// Redact a field value if the field name is sensitive.
    pub fn redact_field(&self, name: &str, value: &str) -> String {
        if self.config.redact_field_names && self.config.is_sensitive_field(name) {
            *self.redaction_count.write() += 1;
            return self.config.redaction_text.clone();
        }

        self.redact(value)
    }

    /// Get the total number of redactions performed.
    pub fn redaction_count(&self) -> u64 {
        *self.redaction_count.read()
    }

    /// Reset the redaction count.
    pub fn reset_count(&self) {
        *self.redaction_count.write() = 0;
    }

    /// Check if text contains PII that would be redacted.
    pub fn contains_pii(&self, text: &str) -> bool {
        let matches = self.detector.scan_text(text);
        matches
            .iter()
            .any(|m| m.classification >= self.config.min_classification)
    }

    /// Get a summary of PII types in text.
    pub fn analyze(&self, text: &str) -> RedactionAnalysis {
        let matches = self.detector.scan_text(text);
        let relevant: Vec<_> = matches
            .iter()
            .filter(|m| m.classification >= self.config.min_classification)
            .collect();

        RedactionAnalysis {
            total_pii_found: matches.len(),
            would_be_redacted: relevant.len(),
            highest_classification: matches
                .iter()
                .map(|m| m.classification)
                .max()
                .unwrap_or(PiiClassification::None),
            pii_types: relevant.iter().map(|m| m.pii_type).collect(),
        }
    }
}

impl Default for LogRedactor {
    fn default() -> Self {
        Self::new()
    }
}

/// Analysis result from redaction check.
#[derive(Debug, Clone)]
pub struct RedactionAnalysis {
    /// Total PII matches found.
    pub total_pii_found: usize,
    /// Number that would be redacted based on configuration.
    pub would_be_redacted: usize,
    /// Highest PII classification found.
    pub highest_classification: PiiClassification,
    /// Types of PII that would be redacted.
    pub pii_types: Vec<PiiType>,
}

impl RedactionAnalysis {
    /// Check if any redaction would occur.
    pub fn needs_redaction(&self) -> bool {
        self.would_be_redacted > 0
    }
}

/// A tracing layer that redacts PII from log output.
pub struct RedactingLayer<S> {
    redactor: Arc<LogRedactor>,
    inner: S,
}

impl<S> RedactingLayer<S> {
    /// Create a new redacting layer wrapping another layer.
    pub fn new(inner: S) -> Self {
        Self {
            redactor: Arc::new(LogRedactor::new()),
            inner,
        }
    }

    /// Create a redacting layer with custom configuration.
    pub fn with_config(inner: S, config: RedactionConfig) -> Self {
        Self {
            redactor: Arc::new(LogRedactor::with_config(config)),
            inner,
        }
    }

    /// Get the redactor for manual use.
    pub fn redactor(&self) -> &Arc<LogRedactor> {
        &self.redactor
    }
}

impl<S, N> Layer<S> for RedactingLayer<N>
where
    S: Subscriber + for<'a> LookupSpan<'a>,
    N: Layer<S>,
{
    fn on_event(&self, event: &Event<'_>, ctx: Context<'_, S>) {
        // Forward to inner layer - actual redaction happens in formatting
        self.inner.on_event(event, ctx);
    }

    fn on_enter(&self, id: &tracing::span::Id, ctx: Context<'_, S>) {
        self.inner.on_enter(id, ctx);
    }

    fn on_exit(&self, id: &tracing::span::Id, ctx: Context<'_, S>) {
        self.inner.on_exit(id, ctx);
    }

    fn on_close(&self, id: tracing::span::Id, ctx: Context<'_, S>) {
        self.inner.on_close(id, ctx);
    }
}

/// A formatter that redacts PII from events.
pub struct RedactingFormatter<F> {
    inner: F,
    redactor: Arc<LogRedactor>,
}

impl<F> RedactingFormatter<F> {
    /// Create a new redacting formatter.
    pub fn new(inner: F, redactor: Arc<LogRedactor>) -> Self {
        Self { inner, redactor }
    }
}

impl<S, N, F> FormatEvent<S, N> for RedactingFormatter<F>
where
    S: Subscriber + for<'a> LookupSpan<'a>,
    N: for<'writer> FormatFields<'writer> + 'static,
    F: FormatEvent<S, N>,
{
    fn format_event(
        &self,
        ctx: &FmtContext<'_, S, N>,
        mut writer: format::Writer<'_>,
        event: &Event<'_>,
    ) -> fmt::Result {
        // Create a buffer to capture the formatted output
        let mut buffer = String::new();
        let buffer_writer = format::Writer::new(&mut buffer);

        // Format to buffer
        // Note: This is a simplified implementation. A full implementation
        // would need to intercept and redact individual field values.
        self.inner.format_event(ctx, buffer_writer, event)?;

        // Redact the buffer
        let redacted = self.redactor.redact(&buffer);

        // Write the redacted output
        write!(writer, "{}", redacted)
    }
}

/// Visitor that redacts field values.
pub struct RedactingVisitor<'a> {
    redactor: &'a LogRedactor,
    output: String,
}

impl<'a> RedactingVisitor<'a> {
    /// Create a new redacting visitor.
    pub fn new(redactor: &'a LogRedactor) -> Self {
        Self {
            redactor,
            output: String::new(),
        }
    }

    /// Get the redacted output.
    pub fn into_output(self) -> String {
        self.output
    }
}

impl<'a> tracing::field::Visit for RedactingVisitor<'a> {
    fn record_debug(&mut self, field: &tracing::field::Field, value: &dyn fmt::Debug) {
        let value_str = format!("{:?}", value);
        let redacted = self.redactor.redact_field(field.name(), &value_str);

        if !self.output.is_empty() {
            self.output.push_str(", ");
        }
        self.output
            .push_str(&format!("{}={}", field.name(), redacted));
    }

    fn record_str(&mut self, field: &tracing::field::Field, value: &str) {
        let redacted = self.redactor.redact_field(field.name(), value);

        if !self.output.is_empty() {
            self.output.push_str(", ");
        }
        self.output
            .push_str(&format!("{}=\"{}\"", field.name(), redacted));
    }

    fn record_i64(&mut self, field: &tracing::field::Field, value: i64) {
        if !self.output.is_empty() {
            self.output.push_str(", ");
        }
        self.output.push_str(&format!("{}={}", field.name(), value));
    }

    fn record_u64(&mut self, field: &tracing::field::Field, value: u64) {
        if !self.output.is_empty() {
            self.output.push_str(", ");
        }
        self.output.push_str(&format!("{}={}", field.name(), value));
    }

    fn record_bool(&mut self, field: &tracing::field::Field, value: bool) {
        if !self.output.is_empty() {
            self.output.push_str(", ");
        }
        self.output.push_str(&format!("{}={}", field.name(), value));
    }
}

/// Redact a string in place (convenience function).
pub fn redact(text: &str) -> String {
    LogRedactor::new().redact(text)
}

/// Redact with custom configuration (convenience function).
pub fn redact_with_config(text: &str, config: RedactionConfig) -> String {
    LogRedactor::with_config(config).redact(text)
}

