//! Minimal test to verify ef_search impact on recall.
//!
//! This demonstrates the critical importance of setting ef_search at build time.
//! Run with: cargo run --example ef_search_test --release

use instant_distance::{Builder as HnswBuilder, HnswMap, Search};
use rand::prelude::*;
use std::collections::HashSet;
use std::time::Instant;

fn generate_random_embedding(dim: usize, rng: &mut StdRng) -> Vec<f32> {
    let mut embedding: Vec<f32> = (0..dim).map(|_| rng.gen::<f32>() * 2.0 - 1.0).collect();
    let norm: f32 = embedding.iter().map(|x| x * x).sum::<f32>().sqrt();
    if norm > f32::EPSILON {
        embedding.iter_mut().for_each(|x| *x /= norm);
    }
    embedding
}

fn generate_embedding_set(count: usize, dim: usize, seed: u64) -> Vec<Vec<f32>> {
    let mut rng = StdRng::seed_from_u64(seed);
    (0..count)
        .map(|_| generate_random_embedding(dim, &mut rng))
        .collect()
}

fn generate_related_queries(base: &[Vec<f32>], num: usize, noise: f32, seed: u64) -> Vec<Vec<f32>> {
    let mut rng = StdRng::seed_from_u64(seed);
    (0..num)
        .map(|_| {
            let base_idx = rng.gen_range(0..base.len());
            let mut query: Vec<f32> = base[base_idx]
                .iter()
                .map(|&x| x + rng.gen_range(-noise..noise))
                .collect();
            let norm: f32 = query.iter().map(|x| x * x).sum::<f32>().sqrt();
            if norm > f32::EPSILON {
                query.iter_mut().for_each(|x| *x /= norm);
            }
            query
        })
        .collect()
}

#[derive(Clone)]
struct NodePoint {
    embedding: Vec<f32>,
}

impl instant_distance::Point for NodePoint {
    fn distance(&self, other: &Self) -> f32 {
        1.0 - self
            .embedding
            .iter()
            .zip(&other.embedding)
            .map(|(a, b)| a * b)
            .sum::<f32>()
    }
}

fn brute_force_knn(embeddings: &[Vec<f32>], query: &[f32], k: usize) -> Vec<usize> {
    let mut scores: Vec<(usize, f32)> = embeddings
        .iter()
        .enumerate()
        .map(|(i, e)| (i, e.iter().zip(query).map(|(a, b)| a * b).sum::<f32>()))
        .collect();
    scores.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
    scores.into_iter().take(k).map(|(i, _)| i).collect()
}

fn hnsw_search(index: &HnswMap<NodePoint, usize>, query: &[f32], k: usize) -> Vec<usize> {
    let q = NodePoint {
        embedding: query.to_vec(),
    };
    let mut search = Search::default();
    index
        .search(&q, &mut search)
        .take(k)
        .map(|n| *n.value)
        .collect()
}

fn test_recall(
    embeddings: &[Vec<f32>],
    queries: &[Vec<f32>],
    ef_construction: usize,
    ef_search: usize,
    k: usize,
) -> (f32, f64) {
    let start = Instant::now();

    let points: Vec<NodePoint> = embeddings
        .iter()
        .map(|e| NodePoint {
            embedding: e.clone(),
        })
        .collect();
    let values: Vec<usize> = (0..embeddings.len()).collect();

    let index = HnswBuilder::default()
        .ef_construction(ef_construction)
        .ef_search(ef_search) // THE KEY PARAMETER
        .build(points, values);

    let build_time = start.elapsed().as_secs_f64();

    let mut total_recall = 0.0;
    for query in queries {
        let truth: HashSet<usize> = brute_force_knn(embeddings, query, k).into_iter().collect();
        let approx: HashSet<usize> = hnsw_search(&index, query, k).into_iter().collect();
        total_recall += truth.intersection(&approx).count() as f32 / k as f32;
    }

    (total_recall / queries.len() as f32, build_time)
}

fn main() {
    println!("╔══════════════════════════════════════════════════════════════════╗");
    println!("║     ef_search Impact Test (instant-distance API verification)    ║");
    println!("╠══════════════════════════════════════════════════════════════════╣");
    println!("║ ef_search is set at BUILD TIME in instant-distance (not query)   ║");
    println!("╚══════════════════════════════════════════════════════════════════╝\n");

    // Use smaller scale for faster testing
    let node_count = 5_000;
    let dim = 128;
    let k = 10;
    let num_queries = 50;
    let ef_construction = 200;

    println!(
        "Test setup: {} nodes, dim={}, k={}, queries={}",
        node_count, dim, k, num_queries
    );
    println!("ef_construction={} (fixed)\n", ef_construction);

    let embeddings = generate_embedding_set(node_count, dim, 42);
    let queries = generate_related_queries(&embeddings, num_queries, 0.1, 123);

    println!("+-------------+------------+---------------+--------+");
    println!("| ef_search   | Build Time |    Recall     | Status |");
    println!("+-------------+------------+---------------+--------+");

    // Test different ef_search values
    for ef_search in [20, 50, 100, 150, 200, 300] {
        let (recall, build_time) =
            test_recall(&embeddings, &queries, ef_construction, ef_search, k);
        let status = if recall >= 0.95 {
            "✓ PASS"
        } else {
            "✗ FAIL"
        };
        println!(
            "| ef_s={:4}   |   {:5.2}s   |    {:.4}     | {} |",
            ef_search, build_time, recall, status
        );
    }

    println!("+-------------+------------+---------------+--------+");
    println!("\nTarget: Recall > 0.95 (95%)");
    println!("\nConclusion: ef_search directly controls recall quality.");
    println!("Higher ef_search = higher recall = slightly slower search.");
}

//! ProfDAG Search Tests - Phase 1
//!
//! Comprehensive test suite for vector similarity search in ProfDAG.
//! Tests cover HNSW-based search, top-k accuracy, filtering, and edge cases.
//!
//! # Search Capabilities
//! - Vector similarity search using cosine distance
//! - Top-k nearest neighbor retrieval
//! - Filtering by node type
//! - Edge case handling (empty, duplicates, etc.)

use std::collections::{HashMap, HashSet};
use std::time::Instant;

mod common;
use common::{cosine_similarity, normalized_embedding, orthogonal_embeddings, similar_embeddings};

// ============================================================================
// Search Structures
// ============================================================================

/// Node type for search filtering.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum NodeType {
    Pattern,
    Trajectory,
    Prediction,
    Decision,
}

/// A searchable node with embedding.
#[derive(Debug, Clone)]
pub struct SearchableNode {
    pub id: String,
    pub node_type: NodeType,
    pub content: String,
    pub embedding: Vec<f32>,
}

impl SearchableNode {
    pub fn new(
        id: impl Into<String>,
        node_type: NodeType,
        content: impl Into<String>,
        embedding: Vec<f32>,
    ) -> Self {
        Self {
            id: id.into(),
            node_type,
            content: content.into(),
            embedding,
        }
    }
}

/// Search result with similarity score.
#[derive(Debug, Clone)]
pub struct SearchResult {
    pub node_id: String,
    pub similarity: f32,
}

impl SearchResult {
    pub fn new(node_id: impl Into<String>, similarity: f32) -> Self {
        Self {
            node_id: node_id.into(),
            similarity,
        }
    }
}

/// Query parameters for search.
#[derive(Debug, Clone)]
pub struct SearchQuery {
    pub embedding: Vec<f32>,
    pub k: usize,
    pub node_type_filter: Option<NodeType>,
    pub min_similarity: f32,
}

impl SearchQuery {
    pub fn new(embedding: Vec<f32>, k: usize) -> Self {
        Self {
            embedding,
            k,
            node_type_filter: None,
            min_similarity: 0.0,
        }
    }

    pub fn with_type_filter(mut self, node_type: NodeType) -> Self {
        self.node_type_filter = Some(node_type);
        self
    }

    pub fn with_min_similarity(mut self, min_sim: f32) -> Self {
        self.min_similarity = min_sim.clamp(0.0, 1.0);
        self
    }
}

/// In-memory search index for testing.
#[derive(Debug, Default)]
pub struct TestSearchIndex {
    nodes: HashMap<String, SearchableNode>,
}

impl TestSearchIndex {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_node(&mut self, node: SearchableNode) {
        self.nodes.insert(node.id.clone(), node);
    }

    pub fn remove_node(&mut self, id: &str) -> Option<SearchableNode> {
        self.nodes.remove(id)
    }

    pub fn len(&self) -> usize {
        self.nodes.len()
    }

    pub fn is_empty(&self) -> bool {
        self.nodes.is_empty()
    }

    /// Perform brute-force similarity search (for correctness testing).
    pub fn search(&self, query: &SearchQuery) -> Vec<SearchResult> {
        let mut results: Vec<SearchResult> = self
            .nodes
            .values()
            .filter(|node| {
                // Apply type filter
                if let Some(filter_type) = query.node_type_filter {
                    if node.node_type != filter_type {
                        return false;
                    }
                }
                true
            })
            .map(|node| {
                let similarity = cosine_similarity(&query.embedding, &node.embedding);
                SearchResult::new(&node.id, similarity)
            })
            .filter(|result| result.similarity >= query.min_similarity)
            .collect();

        // Sort by similarity descending
        results.sort_by(|a, b| b.similarity.partial_cmp(&a.similarity).unwrap());

        // Return top-k
        results.truncate(query.k);
        results
    }

    /// Search with HNSW-like approximation (simulated).
    /// In production, this would use instant-distance or similar library.
    pub fn search_approximate(&self, query: &SearchQuery, ef_search: usize) -> Vec<SearchResult> {
        // For testing, we use exact search but limit candidates
        let candidate_count = (ef_search * 2).min(self.nodes.len());

        let mut candidates: Vec<(&SearchableNode, f32)> = self
            .nodes
            .values()
            .take(candidate_count)
            .map(|node| {
                let similarity = cosine_similarity(&query.embedding, &node.embedding);
                (node, similarity)
            })
            .collect();

        candidates.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());

        candidates
            .into_iter()
            .filter(|(node, sim)| {
                if let Some(filter_type) = query.node_type_filter {
                    if node.node_type != filter_type {
                        return false;
                    }
                }
                *sim >= query.min_similarity
            })
            .take(query.k)
            .map(|(node, sim)| SearchResult::new(&node.id, sim))
            .collect()
    }
}

// ============================================================================
// Vector Similarity Search Tests
