mod edge_cases {
    use super::*;

    #[test]
    fn test_duplicate_embeddings() {
        let mut index = TestSearchIndex::new();
        let embedding = normalized_embedding(128);

        // Add multiple nodes with identical embeddings
        for i in 0..5 {
